do $isolation_guard$ begin
 if current_database()<>'cloudtms_test_clone' or current_setting('transaction_isolation')<>'read committed'
  or current_setting('transaction_read_only')<>'off' or current_user<>session_user
  or current_setting('server_version_num')::integer/10000<>17
  or not exists(select 1 from private.cloudtms_database_identity where singleton and environment='TEST' and customer_key is null)
  or not exists(select 1 from private.bpay_next_module_control where id=1 and active_owner='LEGACY' and owner_epoch=1)
  or exists(select 1 from private.cloudtms_database_releases where status='APPLYING') then
  raise exception 'DAILY_ISOLATION_NATIVE_IDENTITY_REQUIRED' using errcode='55000';end if;
 if exists(select 1 from public.tms_users where id='f717d042-0000-4000-8000-000000000001'::uuid) then
  raise exception 'DAILY_ISOLATION_CANARY_MUST_BE_ABSENT' using errcode='55000';end if;
end; $isolation_guard$;

create or replace function private.timesheet_contract_move_reason_v1(p_note text,p_purpose text default 'CONTRACT_CORRECTION')
returns text language plpgsql immutable security definer set search_path='pg_catalog','pg_temp'
as $function$
declare note text; prefix text;
begin
 if p_purpose is null or p_purpose not in('CONTRACT_CORRECTION','DAILY_RATE_CORRECTION') then raise exception 'CORRECTION_PURPOSE_INVALID' using errcode='22023';end if;
 -- ECMAScript TrimString whitespace, matching the shared Worker decoder exactly.
 note:=btrim(coalesce(p_note,''),U&'\0009\000a\000b\000c\000d\0020\00a0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200a\2028\2029\202f\205f\3000\feff');
 if char_length(note)>1969 then raise exception 'CORRECTION_REASON_TOO_LONG' using errcode='22023';end if;
 prefix:=case p_purpose when 'CONTRACT_CORRECTION' then 'Correcting the Contract' else 'Applying updated rates' end;
 return prefix||case when note='' then '' else ' — '||note end;
end;
$function$;

create or replace function private.daily_rate_correction_request_assert_v1(p_args jsonb,p_kind text)
returns void language plpgsql immutable security definer set search_path='pg_catalog','private','pg_temp'
as $function$
declare keys text[]; ids text[]; key text;
begin
 if jsonb_typeof(p_args) is distinct from 'object' or p_args->>'version' is distinct from 'DAILY_RATE_CORRECTION_V1' then
  raise exception 'DAILY_RATE_REQUEST_INVALID' using errcode='22023';end if;
 if p_kind='PREVIEW' then
  keys:=array['version','request_id','actor_user_id','timesheet_id','context_digest','calculation_snapshot','rate_provenance','reason'];
  ids:=array['request_id','actor_user_id','timesheet_id'];
 elsif p_kind='ACCEPT' then
  keys:=array['version','request_id','actor_user_id','operation_id','review_id','review_digest','expected_state_revision'];
  ids:=array['request_id','actor_user_id','operation_id','review_id'];
 elsif p_kind='READ_RESULT' then keys:=array['version','operation_id','actor_user_id'];ids:=array['operation_id','actor_user_id'];
 else raise exception 'DAILY_RATE_REQUEST_INVALID' using errcode='22023';end if;
 if not(p_args ?& keys) or p_args-keys<>'{}'::jsonb then raise exception 'DAILY_RATE_REQUEST_INVALID' using errcode='22023';end if;
 foreach key in array ids loop
  if jsonb_typeof(p_args->key) is distinct from 'string' or p_args->>key !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
   raise exception 'DAILY_RATE_REQUEST_INVALID' using errcode='22023';end if;
 end loop;
 if p_kind='PREVIEW' then
  if jsonb_typeof(p_args->'reason') is distinct from 'string'
   or jsonb_typeof(p_args->'context_digest') not in('string','null')
   or (jsonb_typeof(p_args->'context_digest')='string' and p_args->>'context_digest' !~ '^[0-9a-f]{64}$')
   or jsonb_typeof(p_args->'calculation_snapshot') not in('object','null')
   or jsonb_typeof(p_args->'rate_provenance') not in('object','null') then raise exception 'DAILY_RATE_REQUEST_INVALID' using errcode='22023';end if;
  perform private.timesheet_contract_move_reason_v1(p_args->>'reason','DAILY_RATE_CORRECTION');
 elsif p_kind='ACCEPT' then
  if jsonb_typeof(p_args->'review_digest') is distinct from 'string' or p_args->>'review_digest' !~ '^[0-9a-f]{64}$'
   or jsonb_typeof(p_args->'expected_state_revision') is distinct from 'string'
   or p_args->>'expected_state_revision' !~ '^[1-9][0-9]*$' or length(p_args->>'expected_state_revision')>19 then raise exception 'DAILY_RATE_REQUEST_INVALID' using errcode='22023';end if;
  if (p_args->>'expected_state_revision')::numeric>9223372036854775807 then raise exception 'DAILY_RATE_REQUEST_INVALID' using errcode='22023';end if;
 end if;
end;
$function$;

create or replace function private.daily_rate_correction_health_actor_require_v1(p_actor_user_id uuid,p_lock boolean)
returns void language plpgsql volatile security definer
set search_path=pg_catalog,public,private,pg_temp
as $function$
declare actor public.tms_users%rowtype;
begin
 if p_actor_user_id is null or p_lock is null then raise exception 'DAILY_RATE_ACTOR_NOT_ALLOWED' using errcode='42501';end if;
 if p_lock then select u.* into actor from public.tms_users u where u.id=p_actor_user_id for share;
 else select u.* into actor from public.tms_users u where u.id=p_actor_user_id;end if;
 if actor.id is null or actor.is_active is distinct from true or lower(btrim(actor.role)) is distinct from 'admin'
  or private.weekly_source_pay_actor_allowed_v1(p_actor_user_id) is distinct from true then
  raise exception 'DAILY_RATE_ACTOR_NOT_ALLOWED' using errcode='42501';end if;
end;
$function$;

create or replace function private.daily_rate_correction_health_basis_v1(p_args jsonb,p_lock boolean)
returns jsonb language plpgsql volatile security definer
set search_path=pg_catalog,public,private,pg_temp
as $function$
declare context jsonb; snapshot jsonb; normalized jsonb; actor uuid;
begin
 perform private.daily_rate_correction_request_assert_v1(p_args,'PREVIEW');
 if p_lock is null then raise exception 'DAILY_RATE_LOCK_MODE_REQUIRED' using errcode='22023';end if;
 -- The native rate writer mutex serialises writers but cannot refresh an
 -- already-established RR/serializable snapshot. No generic rehearsal waiver.
 if p_lock and current_setting('transaction_isolation') is distinct from 'read committed' then
  raise exception 'DAILY_RATE_LOCKED_CONTEXT_ISOLATION_REQUIRED' using errcode='55000';end if;
 actor:=(p_args->>'actor_user_id')::uuid;
 perform private.daily_rate_correction_health_actor_require_v1(actor,false);
 context:=private.daily_rate_correction_context_v1((p_args->>'timesheet_id')::uuid,actor,p_lock);
 -- Recheck and lock the real actor AFTER all context/rate waits. A prior
 -- session or pre-wait boolean is not approval after revocation.
 perform private.daily_rate_correction_health_actor_require_v1(actor,p_lock);
 if context->>'context_digest' is distinct from p_args->>'context_digest' then
  raise exception 'REVIEW_STALE' using errcode='40001';end if;
 snapshot:=private.daily_rate_correction_snapshot_assert_v1(context,p_args->'calculation_snapshot',p_args->'rate_provenance',actor);
 normalized:=private.daily_rate_correction_normalized_snapshot_v1(context,snapshot,p_args->'rate_provenance',actor);
 -- This is exactly the existing0955 prospective Daily input, not a Bank DTO.
 return jsonb_build_object('context',context,'calculation_snapshot',snapshot,
  'normalized_snapshot',normalized,'rate_provenance',p_args->'rate_provenance');
end;
$function$;

